using std::string;
using std::vector;
using std::map;
using std::cout;
using std::cerr;
using std::endl;

int currentLineNumber = 1;
int currentColumn = 1;
int tokenStartLine = 1;
int tokenStartColumn = 1;


#define YY_USER_ACTION { \
